{"summary": "Create D3 visualization logic for bubble chart and table linkage", "security_risk": "MEDIUM", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */

(async function main() {
  const statusEl = document.getElementById('load-status');
  const svg = d3.select('#bubble-svg');
  const chartWrap = document.getElementById('chart');
  const tableWrap = document.getElementById('table');
  const tooltip = d3.select('#tooltip');

  const STOCK_CSV_PATH = 'data/stock-descriptions.csv';

  function setStatus(msg) {
    if (statusEl) statusEl.textContent = msg;
  }

  function formatMarketCap(value) {
    const v = +value;
    if (!Number.isFinite(v) || v <= 0) return '—';

    const abs = Math.abs(v);
    const fmt = (num, suffix) => {
      const s = (Math.round(num * 100) / 100).toFixed(2).replace(/\.00$/, '').replace(/(\.[0-9])0$/, '$1');
      return `${s}${suffix}`;
    };

    if (abs >= 1e12) return fmt(v / 1e12, 'T');
    if (abs >= 1e9) return fmt(v / 1e9, 'B');
    if (abs >= 1e6) return fmt(v / 1e6, 'M');
    if (abs >= 1e3) return fmt(v / 1e3, 'K');
    return String(v);
  }

  async function loadStockData() {
    // For maximum "open from file://" compatibility, we keep an embedded fallback.
    // The app still prefers the copied file in /output/data/stock-descriptions.csv.
    const embedded = window.__EMBEDDED_STOCK_CSV__;

    try {
      const rows = await d3.csv(STOCK_CSV_PATH, d3.autoType);
      return { rows, source: `Loaded ${rows.length} rows from ${STOCK_CSV_PATH}` };
    } catch (err) {
      if (!embedded) throw err;
      const rows = d3.csvParse(embedded, d3.autoType);
      return {
        rows,
        source:
          'Loaded embedded CSV fallback (your browser likely blocked local file fetch). ' +
          'To load from /output/data/ directly, serve this folder with a local web server.'
      };
    }
  }

  function normalizeRows(rawRows) {
    return rawRows
      .map((d) => {
        const marketCap = Number.isFinite(+d.marketCap) ? +d.marketCap : null;
        const ticker = (d.ticker || '').trim();
        const sector = (d.sector || 'Unknown').trim();
        const fullName = (d['full name'] || d.fullName || '').trim();
        const country = (d.country || '').trim();
        const website = (d.website || '').trim();

        const isEtf = !(Number.isFinite(marketCap) && marketCap > 0);
        const showTooltip = !isEtf && country && website;

        return {
          ticker,
          sector,
          fullName,
          marketCap,
          country,
          website,
          isEtf,
          showTooltip
        };
      })
      .filter((d) => d.ticker);
  }

  function renderLegend(sectors, color) {
    const legend = d3.select('#legend');
    legend.selectAll('*').remove();

    const items = legend
      .selectAll('.legend-item')
      .data(sectors, (d) => d)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    items.append('span').attr('class', 'legend-swatch').style('background', (d) => color(d));
    items.append('span').text((d) => d);
  }

  function computeSectorCenters(sectors, width, height) {
    const cx = width / 2;
    const cy = height / 2;

    // Place sector centers on a tight ring around the chart center.
    const r = Math.min(width, height) * 0.22;

    const centers = new Map();
    const n = Math.max(1, sectors.length);
    sectors.forEach((s, i) => {
      const a = (i / n) * Math.PI * 2 - Math.PI / 2;
      centers.set(s, {
        x: cx + r * Math.cos(a),
        y: cy + r * Math.sin(a)
      });
    });

    return centers;
  }

  function renderTable(rows, onSelect) {
    tableWrap.innerHTML = '';

    const table = document.createElement('table');
    const thead = document.createElement('thead');
    const trh = document.createElement('tr');

    const headers = ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'];
    headers.forEach((h) => {
      const th = document.createElement('th');
      th.textContent = h;
      trh.appendChild(th);
    });
    thead.appendChild(trh);

    const tbody = document.createElement('tbody');

    rows.forEach((d) => {
      const tr = document.createElement('tr');
      tr.dataset.ticker = d.ticker;

      tr.addEventListener('click', () => onSelect(d.ticker));

      const tdTicker = document.createElement('td');
      tdTicker.textContent = d.ticker;
      tdTicker.className = 'cell-ticker';

      const tdName = document.createElement('td');
      tdName.textContent = d.fullName || '—';

      const tdSector = document.createElement('td');
      tdSector.textContent = d.sector || '—';

      const tdCap = document.createElement('td');
      tdCap.textContent = formatMarketCap(d.marketCap);
      tdCap.className = 'cell-mcap';

      tr.appendChild(tdTicker);
      tr.appendChild(tdName);
      tr.appendChild(tdSector);
      tr.appendChild(tdCap);

      tbody.appendChild(tr);
    });

    table.appendChild(thead);
    table.appendChild(tbody);
    tableWrap.appendChild(table);

    return {
      setSelected(ticker) {
        const trs = tbody.querySelectorAll('tr');
        trs.forEach((tr) => tr.classList.toggle('selected', tr.dataset.ticker === ticker));

        const target = tbody.querySelector(`tr[data-ticker="${CSS.escape(ticker)}"]`);
        if (target) target.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    };
  }

  function renderBubbles(rows, sectors, color, onSelect) {
    const width = Math.max(520, chartWrap.clientWidth - 20);
    const height = 640;

    svg.attr('viewBox', `0 0 ${width} ${height}`);

    svg.selectAll('*').remove();

    const defs = svg.append('defs');
    const glow = defs
      .append('filter')
      .attr('id', 'glow')
      .attr('x', '-50%')
      .attr('y', '-50%')
      .attr('width', '200%')
      .attr('height', '200%');

    glow.append('feGaussianBlur').attr('stdDeviation', '2.5').attr('result', 'coloredBlur');

    const feMerge = glow.append('feMerge');
    feMerge.append('feMergeNode').attr('in', 'coloredBlur');
    feMerge.append('feMergeNode').attr('in', 'SourceGraphic');

    const centers = computeSectorCenters(sectors, width, height);

    const caps = rows.map((d) => d.marketCap).filter((v) => Number.isFinite(v) && v > 0);
    const capExtent = d3.extent(caps);

    const rScale = d3
      .scaleSqrt()
      .domain(capExtent[0] != null ? capExtent : [1, 1])
      .range([14, 60]);

    const ETF_RADIUS = 18;

    const nodes = rows.map((d) => ({
      ...d,
      r: d.isEtf ? ETF_RADIUS : rScale(d.marketCap),
      x: width / 2 + (Math.random() - 0.5) * 50,
      y: height / 2 + (Math.random() - 0.5) * 50
    }));

    const g = svg.append('g');

    g.append('text')
      .attr('x', 12)
      .attr('y', 24)
      .attr('fill', 'rgba(233, 238, 252, 0.9)')
      .attr('font-size', 12)
      .attr('font-weight', 700)
      .text('Bubble size: market cap (ETFs uniform) · Color: sector · Click to select');

    const nodeG = g
      .append('g')
      .attr('transform', 'translate(0, 6)')
      .selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .style('cursor', 'pointer');

    const circles = nodeG
      .append('circle')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector))
      .attr('fill-opacity', 0.88)
      .attr('stroke', 'rgba(255, 255, 255, 0.16)')
      .attr('stroke-width', 1)
      .attr('filter', 'url(#glow)');

    const labels = nodeG
      .append('text')
      .attr('text-anchor', 'middle')
      .attr('dominant-baseline', 'middle')
      .attr('pointer-events', 'none')
      .attr('fill', 'rgba(0, 0, 0, 0.70)')
      .attr('font-weight', 900)
      .attr('font-size', (d) => (d.r >= 24 ? 12 : 10))
      .text((d) => d.ticker);

    function showTip(event, d) {
      if (!d.showTooltip) return;

      tooltip
        .html(
          `<div class="tt-title">${escapeHtml(d.ticker)} · ${escapeHtml(d.fullName)}</div>` +
            `<div class="tt-row">Sector: ${escapeHtml(d.sector)}</div>`
        )
        .classed('visible', true)
        .attr('aria-hidden', 'false');

      moveTip(event);
    }

    function moveTip(event) {
      const pad = 14;
      const x = Math.min(window.innerWidth - 20, event.clientX + pad);
      const y = Math.min(window.innerHeight - 20, event.clientY + pad);
      tooltip.style('left', `${x}px`).style('top', `${y}px`);
    }

    function hideTip() {
      tooltip.classed('visible', false).attr('aria-hidden', 'true');
    }

    nodeG
      .on('mouseenter', (event, d) => showTip(event, d))
      .on('mousemove', (event) => moveTip(event))
      .on('mouseleave', () => hideTip())
      .on('click', (event, d) => {
        event.preventDefault();
        onSelect(d.ticker);
      });

    const sim = d3
      .forceSimulation(nodes)
      .velocityDecay(0.22)
      .force('center', d3.forceCenter(width / 2, height / 2 + 10))
      .force(
        'x',
        d3
          .forceX((d) => centers.get(d.sector)?.x ?? width / 2)
          .strength(0.08)
      )
      .force(
        'y',
        d3
          .forceY((d) => centers.get(d.sector)?.y ?? height / 2)
          .strength(0.08)
      )
      .force('collide', d3.forceCollide((d) => d.r + 1.2).iterations(2))
      .force('charge', d3.forceManyBody().strength(-6))
      .on('tick', () => {
        nodeG.attr('transform', (d) => `translate(${d.x},${d.y})`);
      });

    let selectedTicker = null;

    function setSelected(ticker) {
      selectedTicker = ticker;

      circles
        .attr('stroke', (d) => (d.ticker === selectedTicker ? 'rgba(255, 209, 102, 0.95)' : 'rgba(255, 255, 255, 0.16)'))
        .attr('stroke-width', (d) => (d.ticker === selectedTicker ? 3 : 1));

      labels
        .attr('fill', (d) => (d.ticker === selectedTicker ? 'rgba(255, 255, 255, 0.92)' : 'rgba(0, 0, 0, 0.70)'));

      sim.alphaTarget(0.12).restart();
      setTimeout(() => sim.alphaTarget(0), 300);
    }

    return {
      setSelected,
      destroy() {
        sim.stop();
      }
    };
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  setStatus('Loading data…');

  const { rows: rawRows, source } = await loadStockData();
  const rows = normalizeRows(rawRows);

  // Keep the view scoped to the 50-row dataset.
  rows.sort((a, b) => (b.marketCap || -Infinity) - (a.marketCap || -Infinity));

  const sectors = Array.from(new Set(rows.map((d) => d.sector))).sort(d3.ascending);
  const color = d3.scaleOrdinal().domain(sectors).range(d3.schemeSet3);

  renderLegend(sectors, color);

  let currentSelection = null;
  let bubbleView = null;

  const tableView = renderTable(rows, select);

  function select(ticker) {
    currentSelection = ticker;
    tableView.setSelected(ticker);
    if (bubbleView) bubbleView.setSelected(ticker);
  }

  function rerenderBubbles() {
    if (bubbleView) bubbleView.destroy();
    bubbleView = renderBubbles(rows, sectors, color, select);
    if (currentSelection) bubbleView.setSelected(currentSelection);
  }

  rerenderBubbles();

  // Re-render on resize so clusters remain centered and tight.
  let resizeTimer = null;
  window.addEventListener('resize', () => {
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(() => rerenderBubbles(), 120);
  });

  setStatus(source);
})();
"}

