    const table = document.createElement('table');
    const thead = document.createElement('thead');
    const trh = document.createElement('tr');

    const headers = ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'];
    headers.forEach((h) => {
      const th = document.createElement('th');
      th.textContent = h;
      trh.appendChild(th);
    });
    thead.appendChild(trh);

    const tbody = document.createElement('tbody');

    rows.forEach((d) => {
      const tr = document.createElement('tr');
      tr.dataset.ticker = d.ticker;

      tr.addEventListener('click', () => onSelect(d.ticker));

      const tdTicker = document.createElement('td');
      tdTicker.textContent = d.ticker;
      tdTicker.className = 'cell-ticker';

      const tdName = document.createElement('td');
      tdName.textContent = d.fullName || '—';

      const tdSector = document.createElement('td');
      tdSector.textContent = d.sector || '—';

      const tdCap = document.createElement('td');
      tdCap.textContent = formatMarketCap(d.marketCap);
      tdCap.className = 'cell-mcap';

      tr.appendChild(tdTicker);
      tr.appendChild(tdName);
      tr.appendChild(tdSector);
      tr.appendChild(tdCap);

      tbody.appendChild(tr);
    });

    table.appendChild(thead);
    table.appendChild(tbody);
    tableWrap.appendChild(table);

    return {
      setSelected(ticker) {
        const trs = tbody.querySelectorAll('tr');
        trs.forEach((tr) => tr.classList.toggle('selected', tr.dataset.ticker === ticker));

        const target = tbody.querySelector(`tr[data-ticker="${CSS.escape(ticker)}"]`);
        if (target) target.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
      }
    };
  }

  function renderBubbles(rows, sectors, color, onSelect) {
    const width = Math.max(520, chartWrap.clientWidth - 20);
    const height = 640;

    svg.attr('viewBox', `0 0 ${width} ${height}`);

    svg.selectAll('*').remove();

    const defs = svg.append('defs');
    const glow = defs
      .append('filter')
      .attr('id', 'glow')
      .attr('x', '-50%')
      .attr('y', '-50%')
      .attr('width', '200%')
      .attr('height', '200%');

    glow.append('feGaussianBlur').attr('stdDeviation', '2.5').attr('result', 'coloredBlur');

    const feMerge = glow.append('feMerge');
    feMerge.append('feMergeNode').attr('in', 'coloredBlur');
    feMerge.append('feMergeNode').attr('in', 'SourceGraphic');

    const centers = computeSectorCenters(sectors, width, height);

    const caps = rows.map((d) => d.marketCap).filter((v) => Number.isFinite(v) && v > 0);
    const capExtent = d3.extent(caps);

    const rScale = d3
      .scaleSqrt()
      .domain(capExtent[0] != null ? capExtent : [1, 1])
      .range([14, 60]);

    const ETF_RADIUS = 18;

    const nodes = rows.map((d) => ({
      ...d,
      r: d.isEtf ? ETF_RADIUS : rScale(d.marketCap),
      x: width / 2 + (Math.random() - 0.5) * 50,
      y: height / 2 + (Math.random() - 0.5) * 50
    }));

    const g = svg.append('g');

    g.append('text')
      .attr('x', 12)
      .attr('y', 24)
      .attr('fill', 'rgba(233, 238, 252, 0.9)')
      .attr('font-size', 12)
      .attr('font-weight', 700)
      .text('Bubble size: market cap (ETFs uniform) · Color: sector · Click to select');

    const nodeG = g
      .append('g')
      .attr('transform', 'translate(0, 6)')
      .selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .style('cursor', 'pointer');

    const circles = nodeG
      .append('circle')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector))
      .attr('fill-opacity', 0.88)
      .attr('stroke', 'rgba(255, 255, 255, 0.16)')
      .attr('stroke-width', 1)
      .attr('filter', 'url(#glow)');

    const labels = nodeG
      .append('text')
      .attr('text-anchor', 'middle')
      .attr('dominant-baseline', 'middle')
      .attr('pointer-events', 'none')
      .attr('fill', 'rgba(0, 0, 0, 0.70)')
      .attr('font-weight', 900)
      .attr('font-size', (d) => (d.r >= 24 ? 12 : 10))
      .text((d) => d.ticker);

    function showTip(event, d) {
      if (!d.showTooltip) return;

      tooltip
        .html(
          `<div class="tt-title">${escapeHtml(d.ticker)} · ${escapeHtml(d.fullName)}</div>` +
            `<div class="tt-row">Sector: ${escapeHtml(d.sector)}</div>`
