    };
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }

  setStatus('Loading data…');

  const { rows: rawRows, source } = await loadStockData();
  const rows = normalizeRows(rawRows);

  // Keep the view scoped to the 50-row dataset.
  rows.sort((a, b) => (b.marketCap || -Infinity) - (a.marketCap || -Infinity));

  const sectors = Array.from(new Set(rows.map((d) => d.sector))).sort(d3.ascending);
  const color = d3.scaleOrdinal().domain(sectors).range(d3.schemeSet3);

  renderLegend(sectors, color);

  let currentSelection = null;
  let bubbleView = null;

  const tableView = renderTable(rows, select);

  function select(ticker) {
    currentSelection = ticker;
    tableView.setSelected(ticker);
    if (bubbleView) bubbleView.setSelected(ticker);
  }

  function rerenderBubbles() {
    if (bubbleView) bubbleView.destroy();
    bubbleView = renderBubbles(rows, sectors, color, select);
    if (currentSelection) bubbleView.setSelected(currentSelection);
  }

  rerenderBubbles();

  // Re-render on resize so clusters remain centered and tight.
  let resizeTimer = null;
  window.addEventListener('resize', () => {
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(() => rerenderBubbles(), 120);
  });

  setStatus(source);
})();
"}
